    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    for c in range(w):
        if grid[h - 1][c] != 5:
            continue
        seeds = [(r, grid[r][c]) for r in range(h) if grid[r][c] != 0]
        for r in range(h):
            if grid[r][c] == 0:
                # Voronoi-fill vertically; ties go to the lower seed.
                nearest = min(seeds, key=lambda item: (abs(item[0] - r), -item[0]))
                out[r][c] = nearest[1]
    return out
